//! C: `azul.h` (`target/codegen/azul.h`, generated by `doc/src/codegen/v2/lang_c.rs`).
//!
//! Spellings: `Az<Class>_<lowerCamelMethod>(..)` for api.json constructors
//! (`AzCssProperty_textColor`, `AzFloatValue_create`); C-like enums are plain
//! constants `Az<Enum>_<Variant>` (`AzLayoutDisplay_Flex`); tagged unions use
//! the generated variant constructors `Az<Enum>_<lowerCamelVariant>(payload)`
//! (`AzLayoutWidth_px(..)`, unit: `AzLayoutWidth_auto()`); a monomorphized
//! `CssPropertyValue<T>` alias (and a `CssProperty` variant whose constructor
//! name is taken by a hand-written api.json function) has no constructor and
//! is a compound literal `(AzLayoutWidthValue){ .Exact = { .tag =
//! AzLayoutWidthValue_Tag_Exact, .payload = .. } }`; structs are compound
//! literals with designated initializers; a Vec is
//! `AzXxxVec_copyFromPtr((AzXxx[]){ .. }, n)` (empty: `AzXxxVec_create()`);
//! strings are `AzString_copyFromBytes((const uint8_t*)"..", 0, len)`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Item, Module, Prim},
    lang::{
        block_comment_safe, c_escape, expr_doc_top, item_comments, uses_nonfinite_float,
        variant_ctor_method, ExprSyntax,
    },
    CodegenBackend, GeneratedFile,
};

/// The C printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct C;

/// `(AzLayoutWidthValue){ .Exact = { .tag = AzLayoutWidthValue_Tag_Exact, .payload = x } }`
pub(crate) fn c_union_literal(ty: &str, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
    let mut inner = vec![Doc::text(format!(".tag = Az{ty}_Tag_{variant}"))];
    if let Some(payload) = args.into_iter().next() {
        inner.push(Doc::cat(vec![Doc::text(".payload = "), payload]));
    }
    Doc::cat(vec![
        Doc::text(format!("(Az{ty})")),
        Doc::list(
            "{",
            vec![Doc::cat(vec![
                Doc::text(format!(".{variant} = ")),
                Doc::list("{", inner, ", ", "}", true, broken, false),
            ])],
            ", ",
            "}",
            true,
            broken,
            false,
        ),
    ])
}

impl ExprSyntax for C {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let suffix = if ty == Prim::F64 { "" } else { "f" };
        match text {
            "nan" => "NAN".to_string(),
            "inf" => "INFINITY".to_string(),
            "-inf" => "-INFINITY".to_string(),
            _ => format!("{text}{suffix}"),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!(
            "AzString_copyFromBytes((const uint8_t*)\"{}\", 0, {})",
            c_escape(s),
            s.len()
        ))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("Az{class}_{}", snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Az{ty}_{variant}")),
            EnumShape::Tagged => Doc::call(format!("Az{ty}_{}", variant_ctor_method(variant)), args, broken),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                c_union_literal(ty, variant, args, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!(".{k} = ")), v]))
            .collect();
        Doc::cat(vec![
            Doc::text(format!("(Az{ty})")),
            Doc::list("{", fields, ", ", "}", true, broken, true),
        ])
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("Az{ty}_create()"));
        }
        let n = items.len();
        Doc::cat(vec![
            Doc::text(format!("Az{ty}_copyFromPtr")),
            Doc::list(
                "(",
                vec![
                    Doc::cat(vec![
                        Doc::text(format!("(Az{elem}[])")),
                        Doc::list("{", items, ", ", "}", true, broken, true),
                    ]),
                    Doc::text(n.to_string()),
                ],
                ", ",
                ")",
                false,
                broken,
                false,
            ),
        ])
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("/* unsupported: {} */ {{0}}", block_comment_safe(what)))
    }
}

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&C, item) {
        out.push_str(&format!("/* {} */\n", block_comment_safe(line)));
    }
    let body = render(&expr_doc_top(&C, &item.value), "    ", 1);
    out.push_str(&format!(
        "static Az{} {}(void) {{\n    return {body};\n}}\n",
        item.ty,
        item.name.snake()
    ));
    out
}

impl CodegenBackend for C {
    fn lang(&self) -> &'static str {
        "c"
    }

    fn display_name(&self) -> &'static str {
        "C"
    }

    fn extension(&self) -> &'static str {
        "h"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "/* Generated by azul-css codegen (C). Do not edit by hand. */\n#include \"azul.h\"\n",
        );
        if uses_nonfinite_float(m) {
            out.push_str("#include <math.h>\n");
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from("#include <stdio.h>\n#include \"styles.h\"\n\nint main(void) {\n");
        for item in &m.items {
            // the local must not shadow the function it is initialised from
            let name = item.name.snake();
            main.push_str(&format!("    Az{} {name}_value = {name}();\n", item.ty));
            if item.ty.ends_with("Vec") {
                main.push_str(&format!(
                    "    printf(\"{name}: %zu properties\\n\", {name}_value.len);\n"
                ));
            } else {
                main.push_str(&format!("    printf(\"{name}: built\\n\");\n"));
            }
            main.push_str(&format!("    Az{}_delete(&{name}_value);\n", item.ty));
        }
        main.push_str("    return 0;\n}\n");
        vec![
            GeneratedFile {
                path: "styles.h".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.c".to_string(),
                contents: main,
            },
            GeneratedFile {
                path: "Makefile".to_string(),
                contents: "# AZUL_INCLUDE: the directory holding azul.h; AZUL_LIB: the one holding \
                           libazul\nAZUL_INCLUDE ?= .\nAZUL_LIB ?= .\n\napp: main.c styles.h\n\t$(CC) \
                           -o app main.c -I$(AZUL_INCLUDE) -L$(AZUL_LIB) -lazul\n"
                    .to_string(),
            },
        ]
    }
}
